using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Security.Cryptography;using System.Threading.Tasks;using System.Windows.Forms;
namespace CodexLight.Bootstrap {
 internal static class MaintenanceUi {
  static string Hash(byte[] bytes){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static Tuple<string,List<UpgradeFile>> PreparePackage(){string temp=Path.Combine(Path.GetTempPath(),"CodexLight-reviewed-package-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{var files=PayloadInstaller.Manifest().Files.Select(f=>new UpgradeFile(f.Path,f.Size,f.Hash)).ToList();UpgradePlanner.ValidateFiles(files);foreach(var file in files){string source=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"payload",file.Path.Replace('/',Path.DirectorySeparatorChar));for(string? p=source;!string.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("安装包不能经过链接");if(BoundedFile.Hash(source,file.Size)!=file.Sha256.ToLowerInvariant())throw new InvalidOperationException("安装包哈希不匹配");string destination=Path.Combine(temp,file.Path.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(destination)!);BoundedFile.Copy(source,destination,file.Size);if(BoundedFile.Hash(destination,file.Size)!=file.Sha256.ToLowerInvariant())throw new InvalidOperationException("复制后校验失败");}var installer=BoundedFile.Read(Assembly.GetExecutingAssembly().Location,16*1024*1024);var config=System.Text.Encoding.UTF8.GetBytes("<configuration><startup><supportedRuntime version=\"v4.0\" sku=\".NETFramework,Version=v4.8\" /></startup></configuration>");foreach(var item in new[]{Tuple.Create("Uninstall.exe",installer),Tuple.Create("Uninstall.exe.config",config)}){File.WriteAllBytes(Path.Combine(temp,item.Item1),item.Item2);files.Add(new UpgradeFile(item.Item1,item.Item2.Length,Hash(item.Item2)));}return Tuple.Create(temp,files);}catch{Directory.Delete(temp,true);throw;}}
  static bool ConfirmUpgrade(Form owner,string details){using(var dialog=new Form{Text="确认受管文件升级",Width=820,Height=560,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false}){var text=new TextBox{Text=details.Replace("\r\n","\n").Replace("\n",Environment.NewLine),Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill,AccessibleName="升级变更清单"};var row=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48,FlowDirection=FlowDirection.RightToLeft};var cancel=new Button{Text="取消",DialogResult=DialogResult.Cancel,AutoSize=true};var confirm=new Button{Text="确认升级",DialogResult=DialogResult.OK,AutoSize=true};row.Controls.Add(cancel);row.Controls.Add(confirm);dialog.Controls.Add(text);dialog.Controls.Add(row);dialog.AcceptButton=cancel;dialog.CancelButton=cancel;dialog.Shown+=(_,__)=>cancel.Focus();return dialog.ShowDialog(owner)==DialogResult.OK;}}
  public static async Task Run(Form owner,Action<string> report){
   using(var folder=new FolderBrowserDialog{Description="选择现有 Codex Light 目录；未知文件保留，不结束运行中的程序",SelectedPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Apps","codexlight"),ShowNewFolderButton=false}){
    if(folder.ShowDialog(owner)!=DialogResult.OK)return;string target=Path.GetFullPath(folder.SelectedPath).TrimEnd('\\');
    string action="";using(var choice=new Form{Text="选择维护操作",Width=640,Height=180,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var label=new Label{Text=target+"\n升级需预览确认；遗留修复仅登记已核验的原文件；恢复不会删除备份。",Dock=DockStyle.Top,Height=60};var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=50};foreach(string name in new[]{"预览升级","精确遗留修复","恢复未完成维护","取消"}){var button=new Button{Text=name,AutoSize=true};button.Click+=(_,__)=>{action=name;choice.Close();};buttons.Controls.Add(button);}choice.Controls.Add(label);choice.Controls.Add(buttons);choice.ShowDialog(owner);}if(action==""||action=="取消")return;
    Tuple<string,List<UpgradeFile>>? package=null;
    try{
     package=await Task.Run(()=>PreparePackage());var registration=new WindowsUpgradeRegistration(target);var orchestrator=new UpgradeOrchestrator(target,target,package.Item1,package.Item2,registration);
     if(action=="预览升级"){
      var preview=await Task.Run(()=>orchestrator.Preview());string detail="目标："+target+"\n"+string.Join("\n",preview.Plan.Steps.Where(s=>s.Kind!="keep").Select(s=>s.Kind+"  "+s.Path))+"\n保留未知文件："+preview.Plan.PreservedUnknown.Count+"\n"+string.Join("\n",preview.Plan.PreservedUnknown.Select(name=>"保留  "+name))+"\n已关闭程序才可升级；备份保留，不自动运行。";
      if(!ConfirmUpgrade(owner,detail))return;await Task.Run(()=>orchestrator.Apply(preview,true));report("升级完成："+target+"。旧受管文件和记录已保留备份；未启动程序。");
     }else if(action=="精确遗留修复"){
      if(MessageBox.Show(owner,"仅识别本任务已审 v7 的42个精确文件，完整匹配后补写归属receipt和本应用登记。未知文件及程序本体不改。\n目标："+target,"确认遗留修复",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;await Task.Run(()=>orchestrator.RepairLegacy(true));report("精确遗留归属修复完成，程序本体未改；可重新预览升级。");
     }else{
      if(MessageBox.Show(owner,"使用这个原安装包验证日志、路径和计划后恢复。若存在已验证的空遗留锁，将在取得维护互斥锁后移除；未知锁或修改文件不会覆盖。备份保留。\n目标："+target,"确认恢复维护",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;string result=await Task.Run(()=>orchestrator.Recover(true,true));report("维护恢复结果："+result+"；备份保留，未启动程序。");
     }
    }catch(Exception error){report("维护停止："+ErrorDetails.Format(error)+"。不会强制结束程序或删除未知文件；请保留日志和备份。");}
    finally{if(package!=null){try{Directory.Delete(package.Item1,true);}catch{report("临时核验安装包清理失败；不会影响保留的恢复备份。");}}}
   }
  }
 }
}
